package co.kr.badara.campsitejournal.test;
import android.app.*;import android.content.*;import android.os.*;
public class StartupTest extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{for(int pass=0;pass<2;pass++)for(String provider:new String[]{"camfit","thankq","campingtalk","naver"}){Intent intent=new Intent().setClassName("co.kr.badara.campsitejournal","co.kr.badara.campsitejournal.PlatformActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("provider",provider).putExtra("history","{}");Activity activity=startActivitySync(intent);waitForIdleSync();if(activity.isFinishing())throw new AssertionError("Activity finished: "+provider);runOnMainSync(()->{if(activity.findViewById(android.R.id.content)==null)throw new AssertionError("No content");try{java.lang.reflect.Field field=activity.getClass().getDeclaredField("browser");field.setAccessible(true);android.webkit.WebView view=(android.webkit.WebView)field.get(activity);if(view==null||view.getParent()==null||view.getUrl()==null)throw new AssertionError("Browser failed to initialize");}catch(ReflectiveOperationException error){throw new AssertionError(error);}activity.finish();});waitForIdleSync();result.putString(provider+"_"+pass,"opened and closed successfully");}result.putString("result","PASS");finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("result",error.toString());finish(Activity.RESULT_CANCELED,result);}}
}